export type ListMessagesParams = {
  /**
   * Items returned in this page. Defaults to 50; at most 200.
   * @minimum 1
   * @maximum 200
   */
  limit?: number;
  /**
   * The next_cursor returned by the previous page. Omit it for the first page.
   * @minLength 1
   * @maxLength 1024
   */
  cursor?: string;
  mailbox_id?: string;
  service_account_id?: string;
  thread_id?: string;
  /**
   * Only messages in these directions; omit for every direction. Comma-separated, for example `direction=inbound,outbound`.
   * @minItems 1
   * @maxItems 2
   */
  direction?: MessageDirection[];
  /**
   * Only messages in these statuses; omit for every status. Comma-separated, for example `status=accepted,delivered,bounced`.
   * @minItems 1
   * @maxItems 8
   */
  status?: MessageStatus[];
  /**
   * Case-insensitive filter matching the sender email address.
   * @maxLength 320
   */
  from_address?: string;
  /**
   * Case-insensitive filter matching any `to` or `cc` recipient email address.
   * @maxLength 320
   */
  to_address?: string;
  /**
   * Keyword search across subject, snippet, plain-text body, and addresses.
   * @maxLength 500
   */
  q?: string;
  unread_only?: boolean;
  flagged_only?: boolean;
  has_attachments?: boolean;
  /**
   * Inclusive start timestamp (RFC 3339).
   */
  from?: string;
  /**
   * Exclusive end timestamp (RFC 3339).
   */
  to?: string;
};

